export const __testHooks = {
  refreshLibrary: () => {},
  setStructure: (_structure: StructureResult | null) => {},
  setDuration: (_duration: number) => {},
  setDurationReady: (_ready: boolean) => {},
  setResult: (_result: AnalysisResult | null) => {},
  getCurrentTime: () => 0,
};

const { useState, useRef, useEffect } = React;

const VolumeInput = ({
  value,
  onChange,
}: {
  value: number;
  onChange: (val: number) => void;
}) => {
  const [inputValue, setInputValue] = React.useState(value.toString());

  React.useEffect(() => {
    setInputValue(Math.max(1, value).toString());
  }, [value]);

  const handleBlurOrEnter = () => {
    const trimmed = inputValue.trim();
    if (!/^\d+$/.test(trimmed)) {
      setInputValue(value.toString());
      return;
    }
    const num = parseInt(trimmed, 10);
    const clamped = Math.max(1, Math.min(100, num));
    onChange(clamped);
    setInputValue(clamped.toString());
  };

  return (
    <div
      className="flex items-center"
      style={{ fontSize: "10px", color: "#ccc", minWidth: "35px" }}
    >
      <input
        type="text"
        value={inputValue}
        onChange={(e) => setInputValue(e.target.value)}
        onBlur={handleBlurOrEnter}
        onKeyDown={(e) => {
          if (e.key === "Enter") {
            handleBlurOrEnter();
            (e.target as HTMLInputElement).blur();
          }
        }}
        style={{
          width: "22px",
          background: "transparent",
          border: "none",
          borderBottom: "1px solid #555",
          color: "inherit",
          fontSize: "inherit",
          textAlign: "right",
          padding: "0 2px",
          outline: "none",
        }}
      />
      <span style={{ marginLeft: "1px", opacity: 0.8 }}>%</span>
    </div>
  );
};

export default function App() {
  const { session, initialized, initialize, signOut } = useAuthStore();
  const [authMode, setAuthMode] = useState<"landing" | "login" | "register">(
    "landing",
  );
  const [path, setPath] = useState(window.location.pathname);

  useEffect(() => {
    let cleanup: (() => void) | undefined;
    (async () => {
      cleanup = await initialize();
    })();
    return () => cleanup?.();
  }, [initialize]);

  useEffect(() => {
    const onPopState = () => setPath(window.location.pathname);
    window.addEventListener("popstate", onPopState);
