  // Mixer states
  const [volumes, setVolumes] = useState<Record<string, number>>({});
  const [mutes, setMutes] = useState<Record<string, boolean>>({});
  const [solos, setSolos] = useState<Record<string, boolean>>({});

  // Panel toggles
  const [showLyrics, setShowLyrics] = useState(true);
  const [showStructure, setShowStructure] = useState(true);
  const [showLibrary, setShowLibrary] = useState(true);
  const [showStemMixer, setShowStemMixer] = useState(true);

  // API Integration States
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [structure, setStructure] = useState<StructureResult | null>(null);
  const [loading, setLoading] = useState(false);
  // Tracks the async structure fetch independently so the Song Structure panel
  // can show a skeleton and the global "ready" state waits for it.
  const [isStructureLoading, setIsStructureLoading] = useState(false);
  const activeStructureJob = React.useRef<string | null>(null);
  const structurePollRef = React.useRef<ReturnType<typeof setInterval> | null>(null);
  
  // Lyrics polling states
  const [isLyricsLoading, setIsLyricsLoading] = useState(false);
  const [lyricsError, setLyricsError] = useState<string | null>(null);
  const activeLyricsJob = React.useRef<string | null>(null);
  const lyricsPollRef = React.useRef<ReturnType<typeof setInterval> | null>(null);

  const [error, setError] = useState<string | null>(null);
  const [isExporting, setIsExporting] = useState(false);
  const [nowPlaying, setNowPlaying] = useState<{
    title: string;
    artist: string;
  } | null>(null);
  const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);
  const [importProgress, setImportProgress] = useState<{
    stage: string;
    progress: number;
  } | null>(null);

  // Stem separation states
  const [showSeparateStemsModal, setShowSeparateStemsModal] = useState(false);
  const [selectedStems, setSelectedStems] = useState<string[]>([]);
  const [isSeparatingStems, setIsSeparatingStems] = useState(false);
  const [separateStemsProgress, setSeparateStemsProgress] = useState(0);

  const [projects, setProjects] = useState<SongProject[]>([]);
  const [groups, setGroups] = useState<SongGroup[]>([]);
  const [collapsedGroups, setCollapsedGroups] = useState<
    Record<string, boolean>
  >({});
  const [showNewGroupInput, setShowNewGroupInput] = useState(false);
  const [newGroupName, setNewGroupName] = useState("");
  const [urlInput, setUrlInput] = useState("");
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const fetchLibrary = React.useCallback(async () => {
    try {
      const [projectsResp, groupsResp] = await Promise.all([
        authFetch(`${API_URL}/api/library/projects`),
        authFetch(`${API_URL}/api/groups`),
      ]);
      if (projectsResp.ok) {
        const data = await projectsResp.json();
        const normalized = Array.isArray(data) ? data : (data.projects ?? []);
        setProjects(normalized);
      }
      if (groupsResp.ok) {
        const data = await groupsResp.json();
        setGroups(data);
