  }, [authFetch, setProjects, setGroups]);

  const createGroup = async (name: string) => {
    try {
      const resp = await authFetch(`${API_URL}/api/groups`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name }),
      });
      if (resp.ok) {
        setNewGroupName("");
