    } catch (e) {
      console.error("Failed to move song to group", e);
    }
  };

  useEffect(() => {
    if (initialized && session) {
      fetchLibrary();
    }
  }, [initialized, session, fetchLibrary]);

  useEffect(() => {
    return () => {
      if (structurePollRef.current) clearInterval(structurePollRef.current);
      if (lyricsPollRef.current) clearInterval(lyricsPollRef.current);
    };
  }, []);

  const refreshLibrary = () => {
    fetchLibrary();
  };

  const fetchStructureAsync = async (payload: any) => {
    setIsStructureLoading(true);
    if (structurePollRef.current) {
      clearInterval(structurePollRef.current);
      structurePollRef.current = null;
    }

    try {
      const startResp = await authFetch(`${API_URL}/api/analysis/start-structure-job`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      const startData = await startResp.json();
      if (!startResp.ok || startData.status === "error") {
        setIsStructureLoading(false);
        return;
      }

      const jobId: string = startData.job_id;
      activeStructureJob.current = jobId;
      let attempts = 0;
      const maxAttempts = 60; // 2 mins at 2s interval

      structurePollRef.current = setInterval(async () => {
        try {
          attempts++;
          const statusResp = await authFetch(`${API_URL}/api/import/status/${jobId}`);
          const statusData = await statusResp.json();

          if (statusData.status === "done" && statusData.result) {
            if (structurePollRef.current) {
              clearInterval(structurePollRef.current);
              structurePollRef.current = null;
            }
            if (activeStructureJob.current === jobId) {
              setIsStructureLoading(false);
              if (!statusData.result.error) {
                setStructure(statusData.result);
              }
            }
          } else if (statusData.status === "error") {
            if (structurePollRef.current) clearInterval(structurePollRef.current);
            if (activeStructureJob.current === jobId) {
              setIsStructureLoading(false);
            }
          } else if (attempts >= maxAttempts) {
            if (structurePollRef.current) clearInterval(structurePollRef.current);
            if (activeStructureJob.current === jobId) {
              setIsStructureLoading(false);
            }
          }
        } catch (e) {
          console.error("Structure poll error", e);
        }
      }, 2000);
    } catch (e) {
      setIsStructureLoading(false);
    }
  };

  const fetchLyricsAsync = async (
    originalPath: string,
    projectId: string | null,
  ) => {
    if (!originalPath) return;
    setIsLyricsLoading(true);
    setLyricsError(null);
    if (lyricsPollRef.current) {
      clearInterval(lyricsPollRef.current);
      lyricsPollRef.current = null;
    }

    try {
      const startResp = await authFetch(`${API_URL}/api/import/start-lyrics-job`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ filePath: originalPath }),
      });
      const startData = await startResp.json();
      if (!startResp.ok || startData.status === "error") {
        setLyricsError(startData.message || "Failed to start lyrics job");
        setIsLyricsLoading(false);
        return;
      }

      const jobId: string = startData.job_id;
      activeLyricsJob.current = jobId;
      let attempts = 0;
      const maxAttempts = 60; // 2 mins at 2s interval

      lyricsPollRef.current = setInterval(async () => {
        try {
          attempts++;
          const statusResp = await authFetch(`${API_URL}/api/import/status/${jobId}`);
          const statusData = await statusResp.json();

          if (statusData.status === "done" && statusData.result?.lyrics) {
            if (lyricsPollRef.current) {
              clearInterval(lyricsPollRef.current);
              lyricsPollRef.current = null;
            }
            if (activeLyricsJob.current === jobId) {
              setIsLyricsLoading(false);
              const lyrics = statusData.result.lyrics;
              setResult((prev) => (prev ? { ...prev, lyrics } : null));

              if (projectId) {
                try {
                  await authFetch(`${API_URL}/api/songs/${projectId}/lyrics`, {
                    method: "PATCH",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ lyrics }),
                  });
                } catch (e) {
                  console.error("Failed to sync lyrics to server", e);
                }
              }
            }
          } else if (statusData.status === "error") {
            if (lyricsPollRef.current) clearInterval(lyricsPollRef.current);
            if (activeLyricsJob.current === jobId) {
              setIsLyricsLoading(false);
              setLyricsError(statusData.error || "Failed to transcribe lyrics");
            }
          } else if (attempts >= maxAttempts) {
            if (lyricsPollRef.current) clearInterval(lyricsPollRef.current);
            if (activeLyricsJob.current === jobId) {
              setIsLyricsLoading(false);
              setLyricsError("Lyrics transcription timed out");
            }
          }
        } catch (e) {
          console.error("Lyrics poll error", e);
        }
      }, 2000);
    } catch (e) {
      setIsLyricsLoading(false);
      setLyricsError("Failed to initiate lyrics job");
    }
  };

  __testHooks.refreshLibrary = refreshLibrary;

  const deleteProject = async (id: string) => {
    try {
      await authFetch(
        `${API_URL}/api/library/projects/${id}?deleteFiles=true`,
        {
          method: "DELETE",
        },
      );
      refreshLibrary();
    } catch (e) {
      console.error("Failed to delete project", e);
    }
  };

  const editProject = async (project: SongProject) => {
    const title = window.prompt("Update title", project.title)?.trim();
    if (!title) return;
    const artist = window.prompt("Update artist", project.artist)?.trim();
    if (!artist) return;

    const updatedProject = { title, artist };

    try {
      const resp = await authFetch(
        `${API_URL}/api/library/projects/${project.id}`,
        {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(updatedProject),
        },
      );
      if (!resp.ok) {
        console.error("Failed to update project", await resp.text());
        return;
      }
      refreshLibrary();
    } catch (e) {
      console.error("Failed to update project", e);
    }
  };

  const DEFAULT_STEMS = ["vocals", "drums", "bass", "guitar", "piano", "other"];

  const stems = useRef<Record<string, HTMLAudioElement>>({});
  const stemObjectUrls = useRef<Record<string, string>>({});

  // Initialize stems with empty Audio elements if they don't exist
  useEffect(() => {
    [...DEFAULT_STEMS, "original"].forEach((stem) => {
      if (!stems.current[stem]) {
        stems.current[stem] = Object.assign(new Audio(), {
          crossOrigin: "anonymous",
        });
      }
    });
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const loadStemsFromPath = (stemsMap: Record<string, string>): Promise<void> => {
    return new Promise(async (resolve) => {
      // Clear all existing stem sources first
      Object.values(stems.current).forEach((audio) => {
        audio.src = "";
      });
      Object.values(stemObjectUrls.current).forEach((url) => {
        URL.revokeObjectURL(url);
      });
      stemObjectUrls.current = {};

      const firstStemKey = Object.keys(stemsMap)[0];
      if (!firstStemKey) {
        resolve();
        return;
      }

      setDurationReady(false);
      // Register the handler BEFORE assigning src so the event is never missed,
      // even if the browser resolves metadata from cache synchronously.
      const firstStemEl = stems.current[firstStemKey];
      const onMetadata = () => {
        const rawDuration = firstStemEl.duration;
        if (Number.isFinite(rawDuration) && rawDuration > 0) {
          durationGuardRef.current = rawDuration;
          setDuration(rawDuration);
          setDurationReady(true);
        } else {
          // Duration not yet known (e.g. VBR/streaming) — wait for durationchange
          const onDurationChange = () => {
            const d = firstStemEl.duration;
            if (Number.isFinite(d) && d > 0) {
              durationGuardRef.current = d;
              setDuration(d);
              setDurationReady(true);
              firstStemEl.removeEventListener("durationchange", onDurationChange);
            }
          };
          firstStemEl.addEventListener("durationchange", onDurationChange);
        }
        firstStemEl.removeEventListener("loadedmetadata", onMetadata);
        resolve();
      };
      firstStemEl.addEventListener("loadedmetadata", onMetadata);

      await Promise.all(
        Object.entries(stemsMap).map(async ([stemName, url]) => {
          if (!stems.current[stemName]) {
            stems.current[stemName] = Object.assign(new Audio(), {
              crossOrigin: "anonymous",
            });
          }
          try {
            const resp = await authFetch(url);
            if (!resp.ok) {
              console.error(`Failed to load stem ${stemName}`, await resp.text());
              return;
            }
            const blobUrl = URL.createObjectURL(await resp.blob());
            stemObjectUrls.current[stemName] = blobUrl;
            stems.current[stemName].src = blobUrl;
          } catch (e) {
            console.error(`Failed to load stem ${stemName}`, e);
          }
        }),
      );
    });
  };

  const loadProject = async (p: SongProject) => {
    if (p.extracted_stems && Object.keys(p.extracted_stems).length > 0) {
      await loadStemsFromPath(p.extracted_stems);
      // Reset mixer to default for loaded stems
      const initialVolumes: Record<string, number> = {};
      const initialMutes: Record<string, boolean> = {};
      const initialSolos: Record<string, boolean> = {};
      Object.keys(p.extracted_stems).forEach((stem) => {
        initialVolumes[stem] = 80;
        initialMutes[stem] = false;
        initialSolos[stem] = false;
      });
      setVolumes(initialVolumes);
      setMutes(initialMutes);
      setSolos(initialSolos);
    } else if (p.stemsPath) {
      // Fallback for legacy projects
      // This path is for older projects that only have stemsPath string.
      // We need to fetch individual stem URLs if available, or perhaps
      // trigger a separate-stems if the backend supports it.
      // For now, if stemsPath exists, assume traditional drum/bass/etc. and construct URLs.
      const pathParts = p.stemsPath.split(/[/\\]/);
      const relPath = pathParts.slice(-2).join("/");
      const defaultStemsMap: Record<string, string> = {
        drums: `${API_URL}/api/analysis/audio/${relPath}/drums.mp3`,
        bass: `${API_URL}/api/analysis/audio/${relPath}/bass.mp3`,
        other: `${API_URL}/api/analysis/audio/${relPath}/other.mp3`,
        vocals: `${API_URL}/api/analysis/audio/${relPath}/vocals.mp3`,
      };
      await loadStemsFromPath(defaultStemsMap);
      setVolumes({ drums: 80, bass: 80, other: 80, vocals: 80 });
      setMutes({ drums: false, bass: false, other: false, vocals: false });
      setSolos({ drums: false, bass: false, other: false, vocals: false });
    } else if (p.original_path) {
      // If no stems but we have original track, load it into original for playback
      Object.values(stems.current).forEach((audio) => (audio.src = ""));
      setDurationReady(false);
      const originalEl = stems.current.original;
      const onLocalMetadata = () => {
        const rawDuration = originalEl.duration;
        if (Number.isFinite(rawDuration) && rawDuration > 0) {
          durationGuardRef.current = rawDuration;
          setDuration(rawDuration);
          setDurationReady(true);
        }
        originalEl.removeEventListener("loadedmetadata", onLocalMetadata);
      };
      originalEl.addEventListener("loadedmetadata", onLocalMetadata);
      
      stems.current.original.src = `${API_URL}/api/analysis/audio/${p.original_path}`;
      setVolumes({ original: 80 });
      setMutes({ original: false });
      setSolos({ original: false });
    } else {
      // If no stems, clear all audio elements
      Object.values(stems.current).forEach((audio) => (audio.src = ""));
      setDuration(0);
      setDurationReady(false);
      setVolumes({});
      setMutes({});
      setSolos({});
    }

    setResult({
      title: p.title,
      artist: p.artist,
      bpm: p.bpm,
      key: p.key,
      original_path: p.original_path,
      extracted_stems: p.extracted_stems,
    });
    setNowPlaying({ title: p.title, artist: p.artist });
    setCurrentProjectId(p.id);
    setCurrentTime(0);
    setSliderTime(0);
    setIsPlaying(false);
    setStructure(null);
    setIsStructureLoading(true);

    try {
      const analysisRes = await authFetch(
        `${API_URL}/api/analysis/project/${p.id}`,
      );
      const analysisData = analysisRes.ok ? await analysisRes.json() : null;

      const structureRes = await authFetch(
        `${API_URL}/api/analysis/structure`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            artist: p.artist,
            title: p.title,
            duration: timeSpanToSeconds(p.duration),
            projectId: p.id,
            filePath: p.original_path,
          }),
        },
      );

      const structureData = structureRes.ok
        ? ((await structureRes.json()) as StructureResult)
        : null;

      if (analysisData && analysisData.status === "success") {
        setResult((prev) => ({ ...prev, ...analysisData }));
      }

      if (structureData && !structureData.error) {
        setStructure(structureData);
      }
    } catch (e) {
      console.error("Failed to load project data", e);
    } finally {
      setIsStructureLoading(false);
    }
  };

  const handleYoutubeImport = async () => {
    if (!urlInput) return;
    setLoading(true);
    setError(null);
    setImportProgress({ stage: "⏳ Starting import...", progress: 0 });

    try {
      // Start the async job for quick analysis
      const startResp = await authFetch(
        `${API_URL}/api/import/start-analyze-quick-job`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ url: urlInput }),
        },
      );
      const startData = await startResp.json();
      if (!startResp.ok || startData.status === "error") {
        setError(startData.message || "Failed to start quick analysis");
        setLoading(false);
        setImportProgress(null);
        return;
      }

      const jobId: string = startData.job_id;

      // Poll every 2 seconds
      if (pollRef.current) clearInterval(pollRef.current);
      pollRef.current = setInterval(async () => {
        try {
          const statusResp = await authFetch(
            `${API_URL}/api/import/status/${jobId}`,
          );
          const statusData = await statusResp.json();

          setImportProgress({
            stage: statusData.stage || "...",
            progress: statusData.progress ?? 0,
          });

          if (statusData.status === "done" && statusData.result) {
            clearInterval(pollRef.current!);
            pollRef.current = null;
            setLoading(false);
            setImportProgress(null);

            const data: AnalysisResult = statusData.result;
            setResult({ ...data, original_path: data.original_path });
            const trackTitle = data.title || "Unknown Track";
            const trackArtist = data.artist || "Unknown Artist";
            setNowPlaying({ title: trackTitle, artist: trackArtist });
            setCurrentProjectId(null);
            setUrlInput("");

            // Capture original_path from quick analysis result
            const originalPathOnServer = data.original_path;
            if (originalPathOnServer) {
              setResult((prev) => ({
                ...prev,
                original_path: originalPathOnServer,
              }));
            }

            // Set duration from the quick analysis result
            if (data.duration_seconds && data.duration_seconds > 0) {
              durationGuardRef.current = data.duration_seconds;
              setDuration(data.duration_seconds);
              setDurationReady(true);
            }

            // Load the original track for playback
            Object.values(stems.current).forEach((audio) => (audio.src = ""));
            if (originalPathOnServer) {
              const originalEl = stems.current.original;
              setDurationReady(false);
              const onLocalMetadata = () => {
                const rawDuration = originalEl.duration;
                if (Number.isFinite(rawDuration) && rawDuration > 0) {
                  durationGuardRef.current = rawDuration;
                  setDuration(rawDuration);
                  setDurationReady(true);
                }
                originalEl.removeEventListener("loadedmetadata", onLocalMetadata);
              };
              originalEl.addEventListener("loadedmetadata", onLocalMetadata);
              
              originalEl.src = `${API_URL}/api/analysis/audio/${originalPathOnServer}`;
              setVolumes({ original: 80 });
              setMutes({ original: false });
              setSolos({ original: false });
            } else {
              setVolumes({});
              setMutes({});
              setSolos({});
            }

            // Sync with the real DB record (replaces the optimistic entry with
            // the persisted one that has the correct id and full metadata).
            refreshLibrary();

            fetchStructureAsync({
              artist: trackArtist,
              title: trackTitle,
              duration: data.duration_seconds || 180,
              filePath: data.original_path,
            });

            if (data.original_path) {
              fetchLyricsAsync(data.original_path, currentProjectId);
            }
          } else if (statusData.status === "error") {
            clearInterval(pollRef.current!);
            pollRef.current = null;
            setError(statusData.error || "Import failed");
            setLoading(false);
            setImportProgress(null);
          }
        } catch (pollErr: any) {
          // Network glitch — keep polling
          console.warn("Poll error (will retry):", pollErr.message);
        }
      }, 2000);
    } catch (e: any) {
      setError("Network error: " + e.message);
      setLoading(false);
      setImportProgress(null);
    }
  };

  const fileInputRef = useRef<HTMLInputElement>(null);
  const lyricsScrollRef = useRef<HTMLDivElement>(null);

  // ── Pitch-shift pipeline (Tone.js) ─────────────────────────────────────
  const pitchShiftRef = useRef<PitchShift | null>(null);
  const stemGainNodesRef = useRef<Record<string, GainNode>>({});
  const audioPipelineInitializedRef = useRef(false);

  const initAudioPipeline = () => {
    if (audioPipelineInitializedRef.current) return;
    audioPipelineInitializedRef.current = true; // Guard before any async yields
    try {
      const toneCtx = getContext().rawContext as AudioContext;
      const ps = new PitchShift({
        pitch: transposeSteps,
        windowSize: transposeSteps < 0 ? 0.2 : 0.1,
      });
      ps.toDestination();
      pitchShiftRef.current = ps;
      Object.keys(stems.current).forEach((k) => {
        try {
          const source = toneCtx.createMediaElementSource(stems.current[k]);
          const gain = toneCtx.createGain();
          stemGainNodesRef.current[k] = gain;
          source.connect(gain);
          // ps.input is a Tone.Gain wrapper; .input on that gives the native GainNode
          gain.connect((ps as any).input.input as GainNode);
        } catch (e) {
          console.warn(`[PitchShift] stem "${k}" pipeline error:`, e);
        }
      });
    } catch (e) {
      console.warn("[PitchShift] initAudioPipeline error:", e);
      audioPipelineInitializedRef.current = false; // Allow retry
    }
  };
  // ────────────────────────────────────────────────────────────────────────

  const isManualScrollRef = useRef<boolean>(false);
  const manualScrollTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(
    null,
  );
  const [isDragging, setIsDragging] = useState(false);
  const [sliderTime, setSliderTime] = useState(0);
  const lastLyricIndexRef = useRef<number | null>(null);
  const durationGuardRef = useRef(0);

  // ── Metronome scheduler refs ────────────────────────────────────────────
  /** Web Audio clock time of the next beat to schedule */
  const metroNextBeatTimeRef = useRef<number>(0);
  /** Which beat within the measure we're on (0 = beat 1 accent) */
  const metroBeatCountRef = useRef<number>(0);
  /** setTimeout handle for the lookahead scheduler tick */
  const metroSchedulerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  // ────────────────────────────────────────────────────────────────────────
  const clampTime = (value: number, max: number) => {
    if (!Number.isFinite(value)) return 0;
    if (!Number.isFinite(max) || max <= 0) return Math.max(0, value);
    return Math.max(0, Math.min(value, max));
  };
  const readDuration = () => {
    const activeStemKey = Object.keys(stems.current).find(k => stems.current[k].src) || Object.keys(stems.current)[0];
    if (!activeStemKey) return 0;
    const rawDuration = stems.current[activeStemKey].duration;
    if (Number.isFinite(rawDuration) && rawDuration > 0) {
      durationGuardRef.current = rawDuration;
      return rawDuration;
    }
    return durationGuardRef.current;
  };
  const syncStemsToTime = React.useCallback(
    (time: number) => {
      const safeDuration = readDuration();
      const clamped = clampTime(time, safeDuration);
      const audioElements = Object.values(stems.current);

      // Synchronous tight loop for simultaneous property updates.
      // This ensures the browser receives all seek requests in the same execution block.
      audioElements.forEach((a) => {
        a.currentTime = clamped;
      });

      setCurrentTime(clamped);
      setSliderTime(clamped);
      return clamped;
    },
    [setCurrentTime, setSliderTime],
  );
  // Apply volumes and mutes/solos — uses GainNodes once the pipeline is live
  useEffect(() => {
    const anySolo = Object.values(solos).some((s) => s);
    Object.keys(stems.current).forEach((k) => {
      let vol = (volumes[k] ?? 0 / 100) * (masterVol / 100);
      if (mutes[k]) vol = 0;
      if (anySolo && !solos[k]) vol = 0;
      vol = Math.min(Math.max(vol, 0), 1);

      const gainNode = stemGainNodesRef.current[k];
      if (gainNode) {
        gainNode.gain.value = vol;
      } else {
        stems.current[k].volume = vol;
      }
    });
  }, [volumes, mutes, solos, masterVol]);

  // Update pitch shifter when transposeSteps changes
  useEffect(() => {
    if (pitchShiftRef.current) {
      pitchShiftRef.current.pitch = transposeSteps;
      // Increase window size for downward shifts to mitigate static/artifacts
      pitchShiftRef.current.windowSize = transposeSteps < 0 ? 0.2 : 0.1;
    }
  }, [transposeSteps]);

  // ── Metronome lookahead scheduler ───────────────────────────────────────
  // Uses the Web Audio API clock (audioCtx.currentTime) for drift-free
  // timing. A short setTimeout loop schedules oscillator nodes 100 ms ahead,
  // which fully decouples click accuracy from JS timer jitter.
  // Derived state to control metronome lifecycle
  const isMetroActive = metronomeEnabled && (isPlaying || isCountingIn);

  useEffect(() => {
    // Stop any running scheduler before (re-)starting or disabling
    if (metroSchedulerRef.current !== null) {
      clearTimeout(metroSchedulerRef.current);
      metroSchedulerRef.current = null;
    }

    if (!isMetroActive) return;

    const bpm = result?.bpm ?? 120;
    const beatsPerMeasure = result?.time_signature ?? 4;
    const beatInterval = 60 / bpm; // seconds per beat

    const SCHEDULE_AHEAD_SECS = 0.1; // how far ahead to schedule
    const TICK_MS = 25; // scheduler poll interval

    // Ensure the AudioContext is running (requires a prior user gesture)
    if (audioCtx.state === "suspended") audioCtx.resume();

    // Kick off the first beat slightly in the future so the first
    // oscillator is always scheduled ahead of the current clock
    metroNextBeatTimeRef.current = audioCtx.currentTime + 0.05;
    metroBeatCountRef.current = 0;

    const tick = () => {
      // Schedule every beat that falls within the lookahead window
      while (
        metroNextBeatTimeRef.current <
        audioCtx.currentTime + SCHEDULE_AHEAD_SECS
      ) {
        const isAccent = metroBeatCountRef.current === 0;
        scheduleMetroClick(metroNextBeatTimeRef.current, isAccent);
        metroNextBeatTimeRef.current += beatInterval;
        metroBeatCountRef.current =
          (metroBeatCountRef.current + 1) % beatsPerMeasure;
      }
      // Re-schedule this tick
      metroSchedulerRef.current = setTimeout(tick, TICK_MS);
    };

    tick();

    return () => {
      if (metroSchedulerRef.current !== null) {
        clearTimeout(metroSchedulerRef.current);
        metroSchedulerRef.current = null;
      }
    };
  }, [isMetroActive, result?.bpm, result?.time_signature]);
  // ────────────────────────────────────────────────────────────────────────

  // Sync time
  useEffect(() => {
    const interval = setInterval(() => {
      if (isPlaying) {
        const activeStemKey = Object.keys(stems.current).find(k => stems.current[k].src) || Object.keys(stems.current)[0];
        if (!activeStemKey) return; // No stems to play
        const current = stems.current[activeStemKey].currentTime;
        const safeDuration = readDuration();
        const safeCurrent = clampTime(current, safeDuration);
        setCurrentTime(safeCurrent);
        if (!isDragging) {
          setSliderTime(safeCurrent);
        }

        if (
          result?.lyrics &&
          !isManualScrollRef.current &&
          lyricsScrollRef.current
        ) {
          const lyrics = result.lyrics;
          let activeIdx = lyrics.findIndex(
            (l) => l.start <= current && l.end >= current,
          );
          if (
            activeIdx === -1 &&
            lyrics.length > 0 &&
            current > lyrics[lyrics.length - 1].end
          ) {
            activeIdx = lyrics.length - 1;
          }
          if (activeIdx !== -1 && lastLyricIndexRef.current !== activeIdx) {
            lastLyricIndexRef.current = activeIdx;
            const container = lyricsScrollRef.current;
            const activeElem = container.children[activeIdx] as HTMLElement;
            if (activeElem) {
              const scrollTarget =
                activeElem.offsetTop -
                container.clientHeight / 2 +
                activeElem.clientHeight / 2;
              container.scrollTo({
                top: scrollTarget,
                behavior: "smooth",
              });
            }
          }
        }
      }
    }, 100);
    return () => clearInterval(interval);
  }, [isPlaying, result, isDragging]);

  // Handle playback end (repeat and play/pause icon)
  useEffect(() => {
    const activeStemKey = Object.keys(stems.current).find(k => stems.current[k].src) || Object.keys(stems.current)[0];
    if (!activeStemKey) return;
    const firstAudioElement = stems.current[activeStemKey];
    const handleEnded = () => {
      if (repeatEnabled) {
        syncStemsToTime(0);
        Object.values(stems.current).forEach((a) => a.play());
      } else {
        setIsPlaying(false);
      }
    };
    firstAudioElement.addEventListener("ended", handleEnded);
    return () => {
      firstAudioElement.removeEventListener("ended", handleEnded);
    };
  }, [repeatEnabled, syncStemsToTime]);

  const handleManualScroll = (_e: React.UIEvent<HTMLDivElement>) => {
    isManualScrollRef.current = true;
    if (manualScrollTimeoutRef.current !== null) {
      clearTimeout(manualScrollTimeoutRef.current);
      manualScrollTimeoutRef.current = null;
    }
    manualScrollTimeoutRef.current = setTimeout(() => {
      isManualScrollRef.current = false;
      manualScrollTimeoutRef.current = null;
    }, 3000);
  };

  const handlePlayPause = async () => {
    if (isPlaying) {
      Object.values(stems.current).forEach((a) => a.pause());
      setIsPlaying(false);
      return;
    }

    // Capture the time we want to start from.
    // If we are currently dragging the slider, use that value.
    // Otherwise, we use the current tracked time.
    const targetTime = isDragging ? sliderTime : currentTime;

    // If we were dragging, we need to finalize the seek across all stems.
    if (isDragging) {
      setIsDragging(false);
      syncStemsToTime(targetTime);
    }

    // Resume Tone.js AudioContext (required by browser autoplay policy)
    await toneStart();
    initAudioPipeline();

    // Count-in logic
    if (countInEnabled) {
      setIsCountingIn(true);
      const bpm = result?.bpm ?? 120;
      const beatIntervalMs = (60 / bpm) * 1000;
      let count = 0;
      const interval = setInterval(() => {
        // If metronome is enabled, the scheduler handles clicks.
        // Otherwise, we play a manual click for the count-in.
        if (!metronomeEnabled) playClick();
        count++;
        if (count >= 4) {
          clearInterval(interval);
          setIsCountingIn(false);
          // Final sync before starting playback to ensure all stems are aligned
          syncStemsToTime(targetTime);
          Object.values(stems.current).forEach((a) => a.play());
          setIsPlaying(true);
        }
      }, beatIntervalMs);
      return;
    }

    // Normal play (resume)
    Object.values(stems.current).forEach((a) => a.play());
    setIsPlaying(true);
  };

  const skipToStart = () => {
    // Explicitly reset to start
    syncStemsToTime(0);
    // If not playing, we don't auto-start unless preferred.
    // The previous logic called handlePlayPause(), which we'll keep for consistency
    // with "restart and play" behavior, but now it will correctly use targetTime=0.
    if (!isPlaying) handlePlayPause();
  };

  const seekTime = (offset: number) => {
    // Use the latest audio clock if playing, otherwise the state
    const activeStemKey = Object.keys(stems.current).find(k => stems.current[k].src) || Object.keys(stems.current)[0];
    const baseTime =
      isPlaying && activeStemKey
        ? stems.current[activeStemKey].currentTime
        : currentTime;
    syncStemsToTime(baseTime + offset);
  };

  const jumpToTime = (time: number) => {
    // Ensure the value is a real number even if the API returned a string
    const parsed = parseFloat(String(time));
    if (!Number.isFinite(parsed) || parsed < 0) return;
    syncStemsToTime(parsed);
  };

  // Auto-sync lyrics if a project is created AFTER lyrics were loaded
  React.useEffect(() => {
    if (currentProjectId && result?.lyrics && result.lyrics.length > 0) {
      authFetch(`${API_URL}/api/songs/${currentProjectId}/lyrics`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ lyrics: result.lyrics }),
      }).catch((e) => console.error("Failed to auto-sync lyrics to library:", e));
    }
  }, [currentProjectId, result?.lyrics, authFetch]);

  // Auto-sync structure if a project is created AFTER structure was loaded
  React.useEffect(() => {
    if (currentProjectId && structure?.sections && structure.sections.length > 0) {
      authFetch(`${API_URL}/api/songs/${currentProjectId}/structure`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ sections: structure.sections }),
      }).catch((e) => console.error("Failed to auto-sync structure to library:", e));
    }
  }, [currentProjectId, structure?.sections, authFetch]);

  // Auto-sync chords if a project is created AFTER chords were loaded
  React.useEffect(() => {
    if (currentProjectId && result?.chords && result.chords.length > 0) {
      authFetch(`${API_URL}/api/songs/${currentProjectId}/chords`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ chords: result.chords }),
      }).catch((e) => console.error("Failed to auto-sync chords to library:", e));
    }
  }, [currentProjectId, result?.chords, authFetch]);

  const saveStructureSections = async (sections: Section[]) => {
    setStructure({ sections });
    if (!currentProjectId) return;
    try {
      const resp = await authFetch(
        `${API_URL}/api/songs/${currentProjectId}/structure`,
        {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ sections }),
        },
      );
      if (!resp.ok) {
        console.error("Failed to save song structure", await resp.text());
        alert("Saved locally, but failed to sync structure to the server.");
      }
    } catch (e) {
      console.error("Failed to save song structure", e);
      alert("Saved locally, but failed to sync structure to the server.");
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const f = e.target.files?.[0];
    if (
      f &&
      (f.type === "audio/mpeg" ||
        f.name.endsWith(".mp3") ||
        f.type.includes("audio/"))
    ) {
      analyzeFile(f);
    } else {
      setError("Please select a valid Audio file.");
    }
  };

  const triggerFileInput = () => fileInputRef.current?.click();

  const analyzeFile = async (selectedFile: File) => {
    setLoading(true);
    setError(null);
    // Start with a specific "uploading" state for clarity
    setImportProgress({ stage: "⬆️ Uploading file...", progress: 0 });

    let analysisSucceeded = false;

    try {
      const {
        data: { session },
      } = await supabase.auth.getSession();
      const token = session?.access_token;
      const xhr = new XMLHttpRequest();
      xhr.open("POST", `${API_URL}/api/import/analyze-quick`, true);
      if (token) {
        xhr.setRequestHeader("Authorization", `Bearer ${token}`);
      }

      // This is the key part for upload progress
      xhr.upload.onprogress = (event) => {
        if (event.lengthComputable) {
          const percentComplete = Math.round(
            (event.loaded / event.total) * 100,
          );
          setImportProgress({
            stage: "⬆️ Uploading file...",
            progress: percentComplete,
          });
        }
      };

      xhr.onload = async () => {
        // Once uploaded, we move to the analysis stage
        setImportProgress({ stage: "🤖 Analyzing...", progress: 100 });

        if (xhr.status < 200 || xhr.status >= 300) {
          let errorMsg = `Upload failed with status: ${xhr.status}`;
          try {
            const errData = JSON.parse(xhr.responseText);
            errorMsg =
              errData.error ||
              errData.message ||
              errData.detail ||
              xhr.statusText;
          } catch {
            // response is not json
          }
          setError(errorMsg);
          analysisSucceeded = false;
          return;
        }

        const data: AnalysisResult = JSON.parse(xhr.responseText);
        if (data.error || data.status === "error") {
          setError(data.error || data.message || "Analysis failed on server.");
          analysisSucceeded = false;
          return;
        }

        analysisSucceeded = true;
        setResult(data); // Store the quick analysis results
        const fileName = selectedFile.name.replace(/\.[^.]+$/, "");
        setNowPlaying({ title: fileName, artist: "Local Upload" });
        setCurrentProjectId(null);
        setCurrentTime(0);
        setSliderTime(0);

        // For quick analysis, we get the original_path (temp file on server)
        // Store this for later stem separation.
        const originalPathOnServer = data.original_path;
        if (originalPathOnServer) {
          setResult((prev) => ({
            ...prev,
            original_path: originalPathOnServer,
          }));
        }

        // Set duration from the quick analysis result
        if (data.duration_seconds && data.duration_seconds > 0) {
          durationGuardRef.current = data.duration_seconds;
          setDuration(data.duration_seconds);
          setDurationReady(true);
        } else {
          // Fallback: If no duration from analysis, load local file to get duration
          const objectUrl = URL.createObjectURL(selectedFile);
          const localAudio = new Audio(objectUrl);
          localAudio.addEventListener("loadedmetadata", () => {
            if (localAudio.duration && localAudio.duration > 0) {
              durationGuardRef.current = localAudio.duration;
              setDuration(localAudio.duration);
              setDurationReady(true);
            }
            URL.revokeObjectURL(objectUrl); // Clean up
          });
        }

        // No stems are loaded yet with analyze-quick, so don't call loadStemsFromPath
        // Instead, load the original file into the original stem for playback
        const objectUrl = URL.createObjectURL(selectedFile);
        setDurationReady(false); // Reset while loading local original
        Object.values(stems.current).forEach((audio) => (audio.src = ""));
        const originalEl = stems.current.original;
        const onLocalMetadata = () => {
          const rawDuration = originalEl.duration;
          if (Number.isFinite(rawDuration) && rawDuration > 0) {
            durationGuardRef.current = rawDuration;
            setDuration(rawDuration);
            setDurationReady(true);
          }
          originalEl.removeEventListener("loadedmetadata", onLocalMetadata);
        };
        originalEl.addEventListener("loadedmetadata", onLocalMetadata);
        // Only load the "original" stem
        stems.current.original.src = objectUrl;
        // Reset current mixer states as only "original" is playing
        setVolumes({ original: 80 });
        setMutes({ original: false });
        setSolos({ original: false });

        fetchStructureAsync({
          artist: "Local Upload",
          title: fileName,
          duration: data.duration_seconds || 180,
          filePath: data.original_path,
        });

        if (data.original_path) {
          fetchLyricsAsync(data.original_path, currentProjectId);
        }
      };

      xhr.onerror = () => {
        setError("A network error occurred during the upload.");
        analysisSucceeded = false;
      };

      // This part runs after the 'onload' and 'onerror' handlers are defined.
      // It needs a final block to clean up state.
      xhr.onloadend = () => {
        if (analysisSucceeded) {
          refreshLibrary();
          setImportProgress(null); // Clear progress on success
        } else {
          // Also clear progress on failure, error is already set
          setImportProgress(null);
        }
        setLoading(false);
      };

      const form = new FormData();
      form.append("file", selectedFile);
      xhr.send(form);
    } catch (e: any) {
      setError("An unexpected error occurred: " + e.message);
      setLoading(false);
      setImportProgress(null);
    }
  };

  // ── Separate Stems Function ────────────────────────────────────────────────
  const handleSeparateStems = async () => {
    if (!result || (!result.original_path && !currentProjectId)) {
      setError("No audio loaded to separate stems.");
      return;
    }
    if (selectedStems.length === 0) {
      setError("Please select at least one stem to separate.");
      return;
    }

    setShowSeparateStemsModal(false);
    setIsSeparatingStems(true);
    setSeparateStemsProgress(0);
    setImportProgress({
      stage: "🎚️ Separating stems...",
      progress: 0,
    }); // Reuse import progress indicator for now

    try {
      const formData = new FormData();
      formData.append("stems", selectedStems.join(","));

      const apiEndpoint = `${API_URL}/api/import/separate-stems`;

      // If we have an original_path (from local upload or URL quick analysis)
      // use that to tell the backend where the file is.
      if (result.original_path) {
        formData.append("originalFilePath", result.original_path);
      } else if (currentProjectId) {
        // If it's a library project without separated stems, we need to
        // figure out how to pass the source file to the Python engine.
        // For now, this branch is not fully implemented as original_path
        // is designed for the current session's analysis.
        setError(
          "Stem separation for existing library projects not yet fully implemented.",
        );
        setIsSeparatingStems(false);
        setImportProgress(null);
        return;
      } else {
        setError("Cannot determine source file for stem separation.");
        setIsSeparatingStems(false);
        setImportProgress(null);
        return;
      }

      const resp = await authFetch(apiEndpoint, {
        method: "POST",
        body: formData,
      });

      if (!resp.ok) {
        let errorMsg = `Stem separation failed: HTTP ${resp.status}`;
        try {
          const errData = await resp.json();
          errorMsg = errData.message || errorMsg;
        } catch {
          // response is not json
        }
        setError(errorMsg);
        setIsSeparatingStems(false);
        setImportProgress(null);
        return;
      }

      const data: { extracted_stems: Record<string, string> } =
        await resp.json();

      if (
        data.extracted_stems &&
        Object.keys(data.extracted_stems).length > 0
      ) {
        // Preserve current time and play state
        const savedTime = currentTime;
        const wasPlaying = isPlaying;

        // Update the result state with the new extracted stems
        setResult((prev) => ({
          ...prev,
          extracted_stems: data.extracted_stems,
        }));
        // Load the newly separated stems into the audio elements
        await loadStemsFromPath(data.extracted_stems);

        // Reset mixer states for the newly loaded stems
        const initialVolumes: Record<string, number> = {};
        const initialMutes: Record<string, boolean> = {};
        const initialSolos: Record<string, boolean> = {};
        Object.keys(data.extracted_stems).forEach((stem) => {
          initialVolumes[stem] = 80;
          initialMutes[stem] = false;
          initialSolos[stem] = false;
        });
        setVolumes(initialVolumes);
        setMutes(initialMutes);
        setSolos(initialSolos);

        // Restore time and playback
        syncStemsToTime(savedTime);
        if (wasPlaying) {
          Object.values(stems.current).forEach((a) => {
            if (a.src) a.play();
          });
        }
      } else {
        setError("Stem separation returned no stems.");
      }
    } catch (e: any) {
      setError("Network error during stem separation: " + e.message);
    } finally {
      setIsSeparatingStems(false);
      setImportProgress(null);
    }
  };

  const formatTime = (sec: number) => {
    if (!Number.isFinite(sec) || sec < 0) return "00:00";
    const m = Math.floor(sec / 60);
    const s = Math.floor(sec % 60);
    return `${m.toString().padStart(2, "0")}:${s.toString().padStart(2, "0")}`;
  };

  const setMixerVolume = (stem: string, val: number) => {
    setVolumes((prev) => ({ ...prev, [stem]: val }));
  };

  const toggleMute = (stem: string) => {
    setMutes((prev) => ({ ...prev, [stem]: !prev[stem] }));
  };

  const toggleSolo = (stem: string) => {
    setSolos((prev) => ({ ...prev, [stem]: !prev[stem] }));
  };

  // ── Export Mix ────────────────────────────────────────────────────────────
  const handleExportMix = async () => {
    if (!durationReady || duration <= 0) {
      alert("Load a song before exporting.");
      return;
    }
    if (isExporting) return;
    setIsExporting(true);
    try {
      const stemKeys = Object.keys(stems.current);
      const anySolo = Object.values(solos).some((s) => s);

      // Decode each stem's MP3 into an AudioBuffer via a temporary AudioContext
      const decodingCtx = new AudioContext();
      const decoded = await Promise.all(
        stemKeys.map(async (k) => {
          const src = stems.current[k].src;
          if (!src) return null;
          try {
            const resp = await authFetch(src);
            if (!resp.ok) return null;
            const ab = await resp.arrayBuffer();
            return decodingCtx.decodeAudioData(ab);
          } catch {
            return null;
          }
        }),
      );
      await decodingCtx.close();

      const validBuffers = decoded.filter(Boolean) as AudioBuffer[];
      if (validBuffers.length === 0) {
        alert("No audio data available to export.");
        return;
      }

      const maxLength = Math.max(...validBuffers.map((b) => b.length));
      const sampleRate = validBuffers[0].sampleRate;

      // Render the mix offline
      const offlineCtx = new OfflineAudioContext(2, maxLength, sampleRate);

      stemKeys.forEach((k, i) => {
        const buf = decoded[i];
        if (!buf) return;

        let vol = (volumes[k] ?? 0 / 100) * (masterVol / 100);
        if (mutes[k]) vol = 0;
        if (anySolo && !solos[k]) vol = 0;
        vol = Math.max(0, Math.min(1, vol));

        const source = offlineCtx.createBufferSource();
        source.buffer = buf;

        const gain = offlineCtx.createGain();
        gain.gain.value = vol;

        source.connect(gain);
        gain.connect(offlineCtx.destination);
        source.start(0);
      });

      const rendered = await offlineCtx.startRendering();
      const wavArrayBuffer = encodeWav(rendered);

      const blob = new Blob([wavArrayBuffer], { type: "audio/wav" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      const trackName = nowPlaying
        ? `${nowPlaying.artist} - ${nowPlaying.title}`
        : "mix";
      a.href = url;
      a.download = `${trackName}.wav`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error("[ExportMix]", err);
      alert("Export failed. See console for details.");
    } finally {
      setIsExporting(false);
    }
  };
  // ─────────────────────────────────────────────────────────────────────────

  const updateTranspose = (delta: number) => {
    setTransposeSteps((prev) => {
      const next = Math.max(-12, Math.min(12, prev + delta));
      setTransposeEnabled(next !== 0);
      return next;
    });
  };

  // ── Scale data (derived, recomputed on every render) ──────────────────────
  const { root: _scaleRoot, type: _scaleType } = parseKey(result?.key ?? "");
  const scaleNotes = getScale(_scaleRoot, _scaleType, transposeSteps);
  // Binary search for the active chord
  let activeChordIdx = -1;
  if (result?.chords && result.chords.length > 0) {
    let low = 0;
    let high = result.chords.length - 1;
    while (low <= high) {
      const mid = Math.floor((low + high) / 2);
      if (result.chords[mid].time <= currentTime) {
        activeChordIdx = mid;
        low = mid + 1;
      } else {
        high = mid - 1;
      }
    }
  }

  const activeChordDisplay =
    activeChordIdx !== -1
      ? transposeChord(result!.chords![activeChordIdx].chord, transposeSteps)
      : null;
  const activeChordTones: Set<string> = activeChordDisplay
    ? new Set(getChordNotes(activeChordDisplay))
    : new Set();
  const displayKey = result?.key
    ? transposeKey(result.key, transposeSteps)
    : null;

  const upcomingChords =
    result?.chords && activeChordIdx !== -1
      ? result.chords.slice(activeChordIdx + 1, activeChordIdx + 4)
      : [];

  const _scaleDegreesLabel =
    _scaleType === "major"
      ? ["I", "II", "III", "IV", "V", "VI", "VII"]
      : ["i", "ii", "♭III", "iv", "v", "♭VI", "♭VII"];
  // ─────────────────────────────────────────────────────────────────────────

  const canSeparateStems =
    nowPlaying !== null && // A song is loaded
    result?.original_path !== undefined && // We have the original path to the file on the server
    (!result?.extracted_stems ||
      Object.keys(result.extracted_stems).length === 0); // Stems haven't been separated yet

  const renderProjectRow = (p: SongProject) => (
    <div
      key={p.id}
      className="glass-panel-inner mb-1 flex justify-between"
      style={{ cursor: "pointer", padding: "6px 8px" }}
      onClick={() => loadProject(p)}
    >
      <div style={{ flex: 1, minWidth: 0 }}>
        <div
          style={{
            color: "white",
            fontWeight: "bold",
            fontSize: "13px",
            whiteSpace: "nowrap",
            overflow: "hidden",
            textOverflow: "ellipsis",
          }}
        >
          {p.title}
        </div>
        <div
          style={{
            color: "#aaa",
            fontSize: "11px",
          }}
        >
          {p.artist}
        </div>
      </div>
      <div className="flex gap-1 items-center ml-2">
        <select
          className="input-dark"
          style={{ fontSize: "9px", padding: "2px", width: "70px" }}
          value={p.groupId || ""}
          onClick={(e) => e.stopPropagation()}
          onChange={(e) => {
            e.stopPropagation();
            moveSongToGroup(p.id, e.target.value || null);
          }}
          title="Move to group"
        >
          <option value="">Ungrouped</option>
          {groups.map((g) => (
            <option key={g.id} value={g.id}>
              {g.name}
            </option>
          ))}
        </select>
        <button
          className="btn-icon"
          style={{ fontSize: "10px" }}
          onClick={(e) => {
            e.stopPropagation();
            editProject(p);
          }}
          title="Edit"
        >
          ✏️
        </button>
        <button
          className="btn-icon"
          style={{ fontSize: "10px", color: "#ff4444" }}
          onClick={(e) => {
            e.stopPropagation();
            deleteProject(p.id);
          }}
          title="Delete"
        >
          ❌
        </button>
      </div>
    </div>
  );

  if (!initialized) {
    return <div className="app-container" />;
  }

  if (!session) {
    return (
      <div className="app-container">
        <Landing
          onLogIn={() => {
            setAuthMode("login");
            navigate("/landing");
          }}
          onSignUp={() => {
            setAuthMode("register");
            navigate("/landing");
          }}
        />
        {authMode === "login" && (
          <LoginForm
            onSuccess={() => {
              setAuthMode("landing");
              navigate("/app");
            }}
            onSwitchToRegister={() => setAuthMode("register")}
          />
        )}
        {authMode === "register" && (
          <RegisterForm
            onSuccess={() => {
              setAuthMode("landing");
              navigate("/app");
            }}
            onSwitchToLogin={() => setAuthMode("login")}
          />
        )}
      </div>
    );
  }

  return (
    <div className="app-container">
      {/* COLUMN 1: LIBRARY */}
      <div className={`library-shell ${showLibrary ? "" : "is-collapsed"}`}>
        <button
          className="library-toggle-btn"
          onClick={() => setShowLibrary((prev) => !prev)}
          aria-label={showLibrary ? "Hide library panel" : "Show library panel"}
          title={showLibrary ? "Hide library" : "Show library"}
        >
          {showLibrary ? "◀" : "▶"}
        </button>
        <div className={`col-library ${showLibrary ? "" : "is-collapsed"}`}>
          <div className="glass-panel" style={{ flex: 1 }}>
            <div className="panel-header">
              <span className="section-title" style={{ margin: 0 }}>
                LIBRARY
              </span>
              <div className="flex gap-1">
                <button
                  className="btn-icon"
                  title="Logout"
                  onClick={async () => {
                    await signOut();
                    setAuthMode("landing");
                    navigate("/landing");
                  }}
                >
                  🚪
                </button>
                <button
                  className="btn-icon"
                  title="New Group"
                  onClick={() => setShowNewGroupInput(true)}
                >
                  📁+
                </button>
                <button
                  className="btn-icon"
                  title={
                    nowPlaying
                      ? "Rescan orphaned stems"
                      : "No song loaded — load a song first"
                  }
                  disabled={!nowPlaying}
                  onClick={async () => {
                    if (!nowPlaying) {
                      alert(
                        "No song loaded. Please load a song before rescanning.",
                      );
                      return;
                    }
                    try {
                      const resp = await authFetch(
                        `${API_URL}/api/library/rescan-stems`,
                        { method: "POST" },
                      );
                      const data = await resp.json();
                      console.log("[Rescan] raw API response:", data);

                      if (!resp.ok) {
                        alert(
                          `Rescan failed: ${data.message ?? `HTTP ${resp.status}`}`,
                        );
                        return;
                      }

                      const { added, total } = data as {
                        added: number;
                        total: number;
                      };
                      if (added > 0) fetchLibrary();
                      alert(
                        added === 0
                          ? `Rescan complete — no new stems found (${total} total in library)`
                          : `Rescan: ${added} new stem${added !== 1 ? "s" : ""} added (${total} total)`,
                      );
                    } catch (e: any) {
                      alert("Rescan failed: " + e.message);
                    }
                  }}
                >
                  🔍
                </button>
                <button
                  className="btn-icon"
                  title="Refresh library"
                  onClick={fetchLibrary}
                >
                  ⟳
                </button>
              </div>
            </div>
            <input
              type="text"
              className="input-dark mb-2"
              placeholder="Search..."
            />
            <div className="flex gap-1 mb-2">
              <select className="input-dark">
                <option>Latest</option>
                <option>A-Z</option>
              </select>
            </div>

            {showNewGroupInput && (
              <div className="mb-2 flex gap-1">
                <input
                  className="input-dark"
                  value={newGroupName}
                  onChange={(e) => setNewGroupName(e.target.value)}
                  placeholder="Group name..."
                  autoFocus
                  onKeyDown={(e) => {
                    if (e.key === "Enter") createGroup(newGroupName);
                    if (e.key === "Escape") setShowNewGroupInput(false);
                  }}
                />
                <button
                  className="btn-primary"
                  onClick={() => createGroup(newGroupName)}
                >
                  Add
                </button>
                <button
                  className="btn-icon"
                  onClick={() => setShowNewGroupInput(false)}
                >
                  ✕
                </button>
              </div>
            )}

            <div style={{ overflowY: "auto", flex: 1, paddingRight: "5px" }}>
              {/* GROUPS */}
              {groups.map((group) => {
                const groupSongs = projects.filter(
                  (p) => p.groupId === group.id,
                );
                const isCollapsed = collapsedGroups[group.id];
                return (
                  <div key={group.id} className="mb-2">
                    <div
                      className="flex items-center justify-between glass-panel-inner p-1 mb-1"
                      style={{
                        background: "rgba(255,255,255,0.05)",
                        cursor: "pointer",
                        border: "1px solid rgba(255,255,255,0.1)",
                      }}
                      onClick={() =>
                        setCollapsedGroups((prev) => ({
                          ...prev,
                          [group.id]: !prev[group.id],
                        }))
                      }
                    >
                      <div className="flex items-center gap-1">
                        <span style={{ fontSize: "10px", width: "12px" }}>
                          {isCollapsed ? "▶" : "▼"}
                        </span>
                        <span style={{ fontSize: "12px", fontWeight: "bold" }}>
                          📁 {group.name}
                        </span>
                        <span style={{ fontSize: "10px", color: "#666" }}>
                          ({groupSongs.length})
                        </span>
                      </div>
                      <button
                        className="btn-icon"
                        style={{ fontSize: "10px", color: "#ff4444" }}
                        onClick={(e) => {
                          e.stopPropagation();
                          deleteGroupEntity(group.id);
                        }}
                        title="Delete group"
                      >
                        ❌
                      </button>
                    </div>
                    {!isCollapsed && (
                      <div
                        style={{
                          marginLeft: "12px",
                          borderLeft: "1px solid rgba(255,255,255,0.1)",
                          paddingLeft: "4px",
                        }}
                      >
                        {groupSongs.map((p) => renderProjectRow(p))}
                        {groupSongs.length === 0 && (
                          <div
                            style={{
                              fontSize: "10px",
                              color: "#555",
                              padding: "4px",
                            }}
                          >
                            Empty
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                );
              })}

              {/* UNGROUPED SONGS */}
              {projects
                .filter((p) => !p.groupId)
                .map((p) => renderProjectRow(p))}

              {projects.length === 0 && (
                <div
                  style={{
                    color: "#aaa",
                    fontSize: "11px",
                    textAlign: "center",
                    marginTop: "10px",
                  }}
                >
                  Library is empty
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* COLUMN 2: ANALYSIS & VISUALIZATION */}
      <div className="col-analysis">
        <div className="tabs">
          <button
            className={`tab-button ${activeTab === "chord" ? "active" : ""}`}
            onClick={() => setActiveTab("chord")}
          >
            CHORDS
          </button>
          <button
            className={`tab-button ${activeTab === "scale" ? "active" : ""}`}
            onClick={() => setActiveTab("scale")}
          >
            SCALE
          </button>
        </div>

        <div className="tab-content">
          <div className="flex flex-col gap-2" style={{ flex: 1 }}>
            {activeTab === "chord" && (
              <div className="flex flex-col" style={{ flex: 1, gap: 8 }}>
                <div
                  className="glass-panel-inner text-center"
                  style={{ padding: "8px 10px" }}
                >
                  <div
                    style={{
                      fontSize: "10px",
                      color: "#888",
                      letterSpacing: "2px",
                      marginBottom: 4,
                    }}
                  >
                    ACTIVE CHORD
                  </div>
                  {activeChordDisplay ? (
                    <div
                      style={{
                        fontSize: "20px",
                        fontWeight: "bold",
                        color: "var(--neon-yellow)",
                      }}
                    >
                      {activeChordDisplay}
                    </div>
                  ) : (
                    <div
                      style={{
                        fontSize: 40,
                        fontWeight: "bold",
                        color: "var(--neon-yellow)",
                      }}
                    >
                      {result?.key ?? "—"}
                    </div>
                  )}
                </div>
              </div>
            )}

            {activeTab === "scale" && (
              <div className="flex flex-col" style={{ flex: 1, gap: 8 }}>
                {/* Scale name header */}
                <div
                  className="glass-panel-inner text-center"
                  style={{ padding: "8px 10px" }}
                >
                  <div
                    style={{
                      fontSize: "10px",
                      color: "#888",
                      letterSpacing: "2px",
                      marginBottom: 4,
                    }}
                  >
                    SCALE
                  </div>
                  {displayKey ? (
                    <div
                      style={{
                        fontSize: "20px",
                        fontWeight: "bold",
                        color: "var(--neon-cyan)",
                        letterSpacing: "1px",
                      }}
                    >
                      {displayKey}
                    </div>
                  ) : (
                    <div style={{ fontSize: "13px", color: "#555" }}>
                      Waiting for analysis…
                    </div>
                  )}
                  {displayKey && (
                    <div
                      style={{
                        fontSize: "10px",
                        color: "#666",
                        marginTop: 2,
                      }}
                    >
                      {_scaleType === "major" ? "Major" : "Natural Minor"}
                    </div>
                  )}
                </div>

                {/* Note chips */}
                {scaleNotes.length > 0 ? (
                  <div
                    style={{
                      display: "grid",
                      gridTemplateColumns: "repeat(7, 1fr)",
                      gap: 4,
                    }}
                  >
                    {scaleNotes.map((note, i) => {
                      const isChordTone = activeChordTones.has(note);
                      return (
                        <div
                          key={i}
                          style={{
                            display: "flex",
                            flexDirection: "column",
                            alignItems: "center",
                            gap: 2,
                            background: isChordTone
                              ? "rgba(0,240,255,0.16)"
                              : "rgba(255,255,255,0.04)",
                            border: `1px solid ${
                              isChordTone
                                ? "var(--neon-cyan)"
                                : "rgba(255,255,255,0.09)"
                            }`,
                            borderRadius: 6,
                            padding: "7px 2px 5px",
                            transition: "all 0.2s ease",
                            boxShadow: isChordTone
                              ? "0 0 8px rgba(0,240,255,0.3)"
                              : "none",
                          }}
                        >
                          <span
                            style={{
                              fontSize: "12px",
                              fontWeight: "bold",
                              color: isChordTone ? "var(--neon-cyan)" : "#ccc",
                              lineHeight: 1,
                            }}
                          >
                            {note}
                          </span>
                          <span
                            style={{
                              fontSize: "9px",
                              color: isChordTone
                                ? "rgba(0,240,255,0.6)"
                                : "#444",
                              fontStyle: "italic",
                              lineHeight: 1,
                            }}
                          >
                            {_scaleDegreesLabel[i]}
                          </span>
                        </div>
                      );
                    })}
                  </div>
                ) : (
                  <div
                    style={{
                      fontSize: "13px",
                      color: "#555",
                      textAlign: "center",
                    }}
                  >
                    {result?.key ? "Unknown scale" : "Waiting for analysis…"}
                  </div>
                )}

                {/* Active chord tones */}
                {activeChordDisplay && (
                  <div className="flex flex-col gap-2">
                    <div
                      className="glass-panel-inner text-center"
                      style={{ padding: "6px 8px" }}
                    >
                      <div
                        style={{
                          fontSize: "10px",
                          color: "#888",
                          letterSpacing: "1px",
                          marginBottom: 3,
                        }}
                      >
                        ACTIVE CHORD
                      </div>
                      <div
                        style={{
                          fontSize: "20px",
                          fontWeight: "bold",
                          color: "var(--neon-yellow)",
                        }}
                      >
                        {activeChordDisplay}
                      </div>
                      <div
                        style={{
                          fontSize: "11px",
                          color: "var(--neon-cyan)",
                          marginTop: 3,
                          letterSpacing: "1px",
                        }}
                      >
                        {[...activeChordTones].join(" · ")}
                      </div>
                    </div>

                    {/* Upcoming row (harmonized) */}
                    {upcomingChords.length > 0 && (
                      <div
                        className="flex items-center justify-center gap-3 px-2 py-1"
                        style={{ opacity: 0.8 }}
                      >
                        {upcomingChords.map((ch, i) => (
                          <div
                            key={i}
                            style={{
                              fontSize: "13px",
                              color: "white",
                              fontWeight: "600",
                            }}
                          >
                            {transposeChord(ch.chord, transposeSteps)}
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                )}

                {/* Footer */}
                {transposeSteps !== 0 && (
                  <div
                    style={{
                      fontSize: "10px",
                      color: "#555",
                      textAlign: "center",
                    }}
                  >
                    Transposed {transposeSteps > 0 ? "+" : ""}
                    {transposeSteps} semitone
                    {Math.abs(transposeSteps) !== 1 ? "s" : ""}
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* COLUMN 3: MAIN WORKSTATION (Now strictly matches Desktop layout) */}
      <div className="col-main">
        {/* ── Main header row ── */}
        <div
          className="flex justify-between items-center"
          style={{ padding: "0 10px" }}
        >
          <h1 className="neon-text-gradient m-0" style={{ fontSize: "24px" }}>
            AI MUSIC WORKSTATION
          </h1>
          <div className="flex items-center gap-2">
            <span
              style={{ fontSize: "10px", fontWeight: "bold", color: "#888" }}
            >
              MASTER VOL
            </span>
            <input
              type="range"
              min="1"
              max="100"
              value={masterVol}
              onChange={(e) => setMasterVol(Number(e.target.value))}
              style={{ width: "80px" }}
            />
            <VolumeInput value={masterVol} onChange={setMasterVol} />
          </div>
        </div>

        {error && (
          <div
            style={{
              background: "rgba(255,0,0,0.1)",
              color: "#ff4444",
              padding: "10px",
              margin: "10px 0",
            }}
          >
            ⚠️ {error}
          </div>
        )}

        {/* Import Section — collapses to Now Playing bar when a song is loaded */}
        {nowPlaying && !loading && !isStructureLoading ? (
          <div
            className="glass-panel"
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              padding: "8px 14px",
            }}
          >
            <div>
              <div
                style={{
                  color: "var(--neon-cyan)",
                  fontSize: 11,
                  fontWeight: "bold",
                  letterSpacing: 1,
                }}
              >
                NOW PLAYING
              </div>
              <div style={{ color: "#fff", fontWeight: "bold", fontSize: 14 }}>
                {nowPlaying.title}
              </div>
              <div style={{ color: "#aaa", fontSize: 11 }}>
                {nowPlaying.artist}
              </div>
            </div>
            <button
              className="btn-icon"
              style={{ fontSize: 11, color: "#aaa", whiteSpace: "nowrap" }}
              onClick={() => {
                setNowPlaying(null);
                setCurrentProjectId(null);
                setResult(null);
                setStructure(null);
                setUrlInput("");
              }}
            >
              ✕ Import new
            </button>
          </div>
        ) : (
          <div className="glass-panel">
            {importProgress ? (
              /* Live progress bar while importing */
              <div style={{ padding: "8px 0" }}>
                <div
                  style={{
                    display: "flex",
                    justifyContent: "space-between",
                    marginBottom: 6,
                  }}
                >
                  <span
                    style={{
                      fontSize: 12,
                      color: "var(--neon-cyan)",
                      fontWeight: "bold",
                    }}
                  >
                    {importProgress.stage}
                  </span>
                  <span style={{ fontSize: 12, color: "#aaa" }}>
                    {importProgress.progress}%
                  </span>
                </div>
                <div
                  style={{
                    background: "rgba(255,255,255,0.08)",
                    borderRadius: 4,
                    height: 8,
                    overflow: "hidden",
                  }}
                >
                  <div
                    style={{
                      height: "100%",
                      width: `${importProgress.progress}%`,
                      background:
                        "linear-gradient(90deg, var(--neon-cyan), var(--neon-magenta))",
                      borderRadius: 4,
                      transition: "width 0.6s ease",
                    }}
                  />
                </div>
                {/* No Demucs message for quick analysis */}
              </div>
            ) : (
              <>
                <div className="flex gap-2 mb-2">
                  <input
                    type="text"
                    className="input-dark"
                    placeholder="Paste YouTube or Spotify Link here..."
                    value={urlInput}
                    onChange={(e) => setUrlInput(e.target.value)}
                    onKeyDown={(e) =>
                      e.key === "Enter" && handleYoutubeImport()
                    }
                  />
                  <button
                    className="btn-accent"
                    style={{
                      background: "rgba(255,0,0,0.1)",
                      color: "#ff4444",
                      borderColor: "#ff4444",
                    }}
                    onClick={handleYoutubeImport}
                    disabled={loading}
                  >
                    ⬇ DOWNLOAD
                  </button>
                </div>
                <input
                  type="file"
                  accept="audio/*"
                  ref={fileInputRef}
                  onChange={handleFileSelect}
                  style={{ display: "none" }}
                />
                <button
                  className="btn-primary"
                  style={{ padding: "12px", width: "100%" }}
                  onClick={triggerFileInput}
                  disabled={loading}
                >
                  {loading
                    ? "⚡ ANALYZING WITH AI..."
                    : "📂 OPEN LOCAL AUDIO FILE"}
                </button>
              </>
            )}
          </div>
        )}

        {/* Analysis Data (Tempo, Key, Transpose, Metronome) */}
        <div className="flex gap-2">
          <div
            className="glass-panel flex-col items-center justify-center"
            style={{ flex: 1 }}
          >
            <span className="section-title">TEMPO</span>
            <div className="analysis-value-row">
              <span
                className="highlight-cyan"
                style={{ fontSize: "40px", fontWeight: "bold" }}
              >
                {result?.bpm ? Math.round(result.bpm) : "—"}
              </span>
              {renderSourceBadge(result?.bpmSource)}
            </div>
          </div>
          <div
            className="glass-panel flex-col items-center justify-center"
            style={{ flex: 1 }}
          >
            <span className="section-title">TIME SIG</span>
            <div className="analysis-value-row">
              <span
                className="highlight-cyan"
                style={{ fontSize: "40px", fontWeight: "bold" }}
              >
                {result?.time_signature ? `${result.time_signature}/4` : "—"}
              </span>
              {renderSourceBadge(result?.timeSigSource)}
            </div>
          </div>
          <div
            className="glass-panel flex-col items-center justify-center"
            style={{ flex: 1 }}
          >
            <span className="section-title">KEY</span>
            <div className="analysis-value-row">
              <span
                className="highlight-cyan"
                style={{ fontSize: "40px", fontWeight: "bold" }}
              >
                {result?.key ? transposeKey(result.key, transposeSteps) : "—"}
              </span>
              {renderSourceBadge(result?.keySource)}
            </div>
          </div>
        </div>

        {/* Transpose & Transport Controls */}
        <div className="glass-panel flex flex-col items-center gap-3">
          {/* Transpose row */}
          <div className="flex items-center gap-2">
            <span
              style={{ fontSize: "10px", fontWeight: "bold", color: "#888" }}
            >
              TRANSPOSE
            </span>
            <button
              className={`btn-icon ${transposeEnabled ? "active" : ""}`}
              onClick={() => updateTranspose(-1)}
              data-testid="transpose-toggle-minus"
            >
              −
            </button>
            <span
              style={{
                fontSize: "16px",
                fontWeight: "bold",
                color: "var(--neon-cyan)",
                minWidth: "28px",
                textAlign: "center",
              }}
            >
              {transposeSteps}
            </span>
            <button
              className={`btn-icon ${transposeEnabled ? "active" : ""}`}
              onClick={() => updateTranspose(1)}
              data-testid="transpose-toggle-plus"
            >
              +
            </button>
          </div>
          {/* Count In / Metro / Repeat — symmetrically centred below transpose */}
          <div className="flex items-center gap-3">
            <button
              className="toggle-btn transport-toggle-btn"
              data-active={countInEnabled ? "true" : "false"}
              onClick={() => setCountInEnabled(!countInEnabled)}
            >
              ⏱ Count In
            </button>
            <button
              className="toggle-btn transport-toggle-btn"
              data-active={metronomeEnabled ? "true" : "false"}
              onClick={() => setMetronomeEnabled(!metronomeEnabled)}
              data-testid="metro-toggle"
            >
              🥁 Metro
            </button>
          </div>
        </div>

        {/* LYRICS PANEL IN THE MIDDLE */}
        <div
          className="glass-panel"
          style={{ flex: 1, display: "flex", flexDirection: "column" }}
        >
          <div className="panel-header">
            <span className="section-title" style={{ margin: 0 }}>
              LYRICS
            </span>
            <button
              className="btn-fold"
              onClick={() => setShowLyrics(!showLyrics)}
              title={showLyrics ? "Collapse panel" : "Expand panel"}
            >
              {showLyrics ? "▲" : "▼"}
            </button>
          </div>
          <div
            className={`panel-content-collapsible ${showLyrics ? "" : "is-folded"}`}
            style={{ flex: 1, display: "flex", flexDirection: "column" }}
          >
            <div
              ref={lyricsScrollRef}
              onScroll={handleManualScroll}
              className="lyrics-container"
              style={{ flex: 1, paddingRight: "5px" }}
            >
              {result?.lyrics && result.lyrics.length > 0 ? (
                result.lyrics.map((seg, idx) => (
                  <p
                    key={idx}
                    className={`lyric-line ${currentTime >= seg.start && currentTime <= seg.end ? "active" : ""}`}
                    onClick={() => jumpToTime(seg.start)}
                  >
                    <span className="lyric-timestamp">
                      [{seg.start.toFixed(1)}s]
                    </span>
                    {seg.text}
                  </p>
                ))
              ) : (
                <div
                  style={{
                    fontSize: "12px",
                    color: lyricsError ? "#ff4444" : "#555",
                    textAlign: "center",
                    marginTop: "20px",
                  }}
                >
                  {lyricsError 
                    ? lyricsError 
                    : isLyricsLoading 
                        ? "Transcribing lyrics with Whisper..." 
                        : "No lyrics data"}
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Mixer */}
        <div className="glass-panel" style={{ paddingBottom: "4px" }}>
          <div className="panel-header">
            <span className="section-title" style={{ margin: 0 }}>
              STEM MIXER
            </span>
            {canSeparateStems && (
              <button
                className="btn-primary"
                onClick={() => setShowSeparateStemsModal(true)}
                disabled={isSeparatingStems || loading}
                title={
                  isSeparatingStems ? "Separating stems..." : "Separate Stems"
                }
                style={{ padding: "4px 10px", fontSize: "10px" }}
              >
                {isSeparatingStems ? "Separating..." : "Separate Stems"}
              </button>
            )}
            <button
              className="btn-fold"
              onClick={() => setShowStemMixer(!showStemMixer)}
              title={showStemMixer ? "Collapse panel" : "Expand panel"}
            >
              {showStemMixer ? "▲" : "▼"}
            </button>
          </div>
          <div
            className={`panel-content-collapsible ${showStemMixer ? "" : "is-folded"}`}
          >
            {/* The original track preview is now handled by the global transport (routed through drums) */}

            <div className="mixer-grid">
              {result?.extracted_stems &&
              Object.keys(result.extracted_stems).length > 0 ? (
                Object.keys(stems.current).filter(s => s !== "original").map((stem) => (
                  <div key={stem} className="mixer-channel">
                    <span
                      style={{
                        fontSize: "11px",
                        fontWeight: "bold",
                        color: "#888",
                      }}
                    >
                      {stem.toUpperCase()}
                    </span>
                    <div className="vertical-slider-container">
                      <input
                        type="range"
                        className="vertical-slider"
                        min="1"
                        max="100"
                        value={volumes[stem] ?? 80}
                        onChange={(e) =>
                          setMixerVolume(stem, Number(e.target.value))
                        }
                      />
                    </div>
                    <VolumeInput
                      value={volumes[stem] ?? 80}
                      onChange={(val) => setMixerVolume(stem, val)}
                    />
                    <div className="flex gap-1">
                      <button
                        className={`toggle-btn toggle-mute ${mutes[stem] ? "active" : ""}`}
                        onClick={() => toggleMute(stem)}
                      >
                        M
                      </button>
                      <button
                        className={`toggle-btn toggle-solo ${solos[stem] ? "active" : ""}`}
                        onClick={() => toggleSolo(stem)}
                      >
                        S
                      </button>
                    </div>
                  </div>
                ))
              ) : nowPlaying &&
                !result?.extracted_stems &&
                result?.original_path ? (
                // If a song is loaded and stems not separated yet, show a placeholder for the original track
                <div key="original" className="mixer-channel">
                  <span
                    style={{
                      fontSize: "11px",
                      fontWeight: "bold",
                      color: "#888",
                    }}
                  >
                    ORIGINAL
                  </span>
                  <div className="vertical-slider-container">
                    <input
                      type="range"
                      className="vertical-slider"
                      min="1"
                      max="100"
                      value={volumes["original"] ?? 80}
                      onChange={(e) =>
                        setMixerVolume("original", Number(e.target.value))
                      }
                    />
                  </div>
                  <VolumeInput
                    value={volumes["original"] ?? 80}
                    onChange={(val) => setMixerVolume("original", val)}
                  />
                  <div className="flex gap-1">
                    <button
                      className={`toggle-btn toggle-mute ${mutes["original"] ? "active" : ""}`}
                      onClick={() => toggleMute("original")}
                    >
                      M
                    </button>
                    <button
                      className={`toggle-btn toggle-solo ${solos["original"] ? "active" : ""}`}
                      onClick={() => toggleSolo("original")}
                    >
                      S
                    </button>
                  </div>
                </div>
              ) : (
                <div
                  style={{
                    fontSize: "12px",
                    color: "#555",
                    textAlign: "center",
                    padding: "20px",
                  }}
                >
                  No stems loaded. Import a song to get started.
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Transport */}
        <div className="glass-panel" style={{ marginTop: "auto" }}>
          <div className="flex items-center gap-2 mb-2">
            <span style={{ fontSize: "12px", color: "#888", width: "40px" }}>
              {formatTime(currentTime)}
            </span>
            <input
              type="range"
              className="timeline-slider"
              data-testid="timeline-slider"
              min="0"
              max={durationReady ? duration : 0}
              value={isDragging ? sliderTime : currentTime}
              onMouseDown={() => setIsDragging(true)}
              onMouseUp={() => setIsDragging(false)}
              onMouseLeave={() => setIsDragging(false)}
              onChange={(e) => {
                const newTime = Number(e.target.value);
                setSliderTime(newTime);
                jumpToTime(newTime);
              }}
              onTouchStart={() => setIsDragging(true)}
              onTouchEnd={() => setIsDragging(false)}
            />
            <span
              style={{
                fontSize: "12px",
                color: "#888",
                width: "40px",
                textAlign: "right",
              }}
            >
              {durationReady ? formatTime(duration) : "--:--"}
            </span>
          </div>
          <div className="flex justify-center items-center gap-2">
            <button
              className={`btn-icon${repeatEnabled ? " active" : ""}`}
              style={{ fontSize: "20px" }}
              title="Loop / Repeat"
              onClick={() => setRepeatEnabled(!repeatEnabled)}
            >
              🔁
            </button>
            <button
              className="btn-icon"
              style={{ fontSize: "24px" }}
              onClick={() => seekTime(-10)}
            >
              «
            </button>
            <button
              className="btn-icon"
              style={{ fontSize: "16px", color: "#ff4444" }}
              onClick={skipToStart}
            >
              ⏮
            </button>
            <button
              className="btn-accent"
              style={{
                width: "60px",
                height: "60px",
                borderRadius: "50%",
                fontSize: "24px",
                padding: 0,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
              onClick={handlePlayPause}
            >
              {isPlaying ? "⏸" : "▶"}
            </button>
            <button
              className="btn-icon"
              style={{ fontSize: "24px" }}
              onClick={() => seekTime(10)}
            >
              »
            </button>
            <button
              className="btn-primary ml-4"
              onClick={handleExportMix}
              disabled={isExporting || !durationReady}
              title={
                !durationReady ? "Load a song first" : "Export stems as WAV mix"
              }
              style={{
                opacity: isExporting || !durationReady ? 0.6 : 1,
                cursor: isExporting
                  ? "wait"
                  : !durationReady
                    ? "not-allowed"
                    : "pointer",
                minWidth: "120px",
              }}
            >
              {isExporting ? "⏳ Exporting…" : "💾 EXPORT MIX"}
            </button>
          </div>
        </div>
      </div>

      {/* COLUMN 4: SECTIONS */}
      <div className="col-sections">
        <SongStructurePanel
          structure={structure}
          isStructureLoading={isStructureLoading}
          onJumpToTime={jumpToTime}
          onSaveSections={saveStructureSections}
          isFolded={!showStructure}
          onToggleFold={() => setShowStructure(!showStructure)}
        />
      </div>
      <SpeedInsights />

      {/* Separate Stems Modal */}
      {showSeparateStemsModal && (
        <div className="modal-overlay">
          <div
            className="modal-content glass-panel"
            style={{ minWidth: "400px" }}
          >
            <h2 className="text-xl font-bold mb-4 neon-text-gradient">
              Separate Stems
            </h2>
            <p className="mb-4 text-sm text-gray-400">
              Select which stems you'd like to extract from the track. More
              stems will take longer to process.
            </p>
            <div className="flex flex-wrap gap-2 mb-6">
              {DEFAULT_STEMS.map((stem) => (
                <label key={stem} className="flex items-center space-x-2">
                  <input
                    type="checkbox"
                    checked={selectedStems.includes(stem)}
                    onChange={(e) => {
                      if (e.target.checked) {
                        setSelectedStems((prev) => [...prev, stem]);
                      } else {
                        setSelectedStems((prev) =>
                          prev.filter((s) => s !== stem),
                        );
                      }
                    }}
                    className="form-checkbox h-4 w-4 text-cyan-600 transition duration-150 ease-in-out"
                  />
                  <span className="text-gray-200 capitalize">{stem}</span>
                </label>
              ))}
            </div>

            {isSeparatingStems && (
              <div className="w-full bg-gray-700 rounded-full h-2.5 mb-4">
                <div
                  className="bg-cyan-600 h-2.5 rounded-full"
                  style={{ width: `${separateStemsProgress}%` }}
                ></div>
              </div>
            )}

            <div className="flex justify-end gap-3">
              <button
                className="btn-secondary"
                onClick={() => {
                  setShowSeparateStemsModal(false);
                  setSelectedStems([]);
                }}
                disabled={isSeparatingStems}
              >
                Cancel
              </button>
              <button
                className="btn-primary"
                onClick={handleSeparateStems}
                disabled={selectedStems.length === 0 || isSeparatingStems}
              >
                {isSeparatingStems ? "Separating..." : "Separate"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
